def oracle(inp):
    n = inp[0]
    k = inp[1]
    a = inp[2]
    b = inp[3]
    dp = {0: 0}
    i = 0
    while i < n:
        x = a[i] - k * b[i]
        w = a[i]
        ndp = {}
        for key in dp:
            val = dp[key]
            if key not in ndp or val > ndp[key]:
                ndp[key] = val
            nk = key + x
            nv = val + w
            if nk not in ndp or nv > ndp[nk]:
                ndp[nk] = nv
        dp = ndp
        i += 1
    if 0 in dp and dp[0] > 0:
        return dp[0]
    return -1

